namespace AutosurBuscador {
using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.Globalization;using System.IO;using System.IO.Compression;using System.Linq;using System.Net;using System.Security.Cryptography;using System.Text;using System.Threading.Tasks;using System.Web.Script.Serialization;using System.Windows.Forms;
public static class UpdateManager {
 public const string AppVersion="1.3.1";
 public const string Repository="juancarlosamarante94-alt/Buscador-Autosur-Objetivos";
 public const string PackageName="Buscador_Autosur_Objetivos_Actualizacion.zip";
 public const string PackageFolder="Buscador_VIN_Instalable";
 public const string AppName="Buscador Autosur Objetivos";
 static string Api {get{return "https://api.github.com/repos/"+Repository;}}
 static string CredentialFile {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),AppName,"datos","github-access.bin");}}
 static byte[] Entropy {get{return Encoding.UTF8.GetBytes(Repository);}}
 public static void SaveAccess(string token){Directory.CreateDirectory(Path.GetDirectoryName(CredentialFile));if(String.IsNullOrWhiteSpace(token)){if(File.Exists(CredentialFile))File.Delete(CredentialFile);return;}var bytes=ProtectedData.Protect(Encoding.UTF8.GetBytes(token.Trim()),Entropy,DataProtectionScope.CurrentUser);File.WriteAllBytes(CredentialFile,bytes);}
 static string Access(){if(!File.Exists(CredentialFile))return "";try{return Encoding.UTF8.GetString(ProtectedData.Unprotect(File.ReadAllBytes(CredentialFile),Entropy,DataProtectionScope.CurrentUser));}catch{throw new Exception("No se pudo abrir el acceso cifrado de GitHub. Configurá nuevamente Acceso GitHub.");}}
 public static bool Configure(Form owner){using(var f=new Form{Text="Acceso de lectura a GitHub",Size=new Size(650,365),StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=false,FormBorderStyle=FormBorderStyle.FixedDialog}){
 var explanation=new Label{Text="Para actualizar desde el repositorio privado, creá un token de acceso\ncon permiso Contents: Read-only únicamente para este repositorio.\nSe guardará cifrado para tu usuario de Windows. No se sube a GitHub.\n\nRepositorio: "+Repository,Location=new Point(18,18),AutoSize=true};f.Controls.Add(explanation);
 var link=new LinkLabel{Text="Abrir configuración de tokens de GitHub",Location=new Point(18,135),AutoSize=true};link.LinkClicked+=delegate{Process.Start("https://github.com/settings/personal-access-tokens");};f.Controls.Add(link);
 f.Controls.Add(new Label{Text="Token de lectura (dejar vacío para quitar el acceso guardado)",Location=new Point(18,175),AutoSize=true});var input=new TextBox{Location=new Point(18,200),Width=590,UseSystemPasswordChar=true};f.Controls.Add(input);
 var save=new Button{Text="Guardar acceso",Location=new Point(340,260),Width=135};save.Click+=delegate{try{SaveAccess(input.Text);input.Clear();f.DialogResult=DialogResult.OK;}catch(Exception ex){MessageBox.Show(f,ex.Message,"Acceso GitHub");}};f.Controls.Add(save);var cancel=new Button{Text="Cancelar",Location=new Point(485,260),Width=120,DialogResult=DialogResult.Cancel};f.Controls.Add(cancel);f.AcceptButton=save;f.CancelButton=cancel;return f.ShowDialog(owner)==DialogResult.OK;}}
 class Client:WebClient {protected override WebRequest GetWebRequest(Uri address){var r=base.GetWebRequest(address);r.Timeout=30000;return r;}}
 static Client Web(string token,bool asset){ServicePointManager.SecurityProtocol=(SecurityProtocolType)3072;var w=new Client();w.Encoding=Encoding.UTF8;w.Headers[HttpRequestHeader.UserAgent]=AppName.Replace(' ','-')+"/"+AppVersion;w.Headers[HttpRequestHeader.Accept]=asset?"application/octet-stream":"application/vnd.github+json";w.Headers["X-GitHub-Api-Version"]="2022-11-28";if(token.Length>0)w.Headers[HttpRequestHeader.Authorization]="Bearer "+token;return w;}
 static Dictionary<string,object> Release(string token){using(var w=Web(token,false))return new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(w.DownloadString(Api+"/releases/latest"));}
 static bool NeedsAccess(WebException ex){var r=ex.Response as HttpWebResponse;return r!=null&&(r.StatusCode==HttpStatusCode.NotFound||r.StatusCode==HttpStatusCode.Unauthorized||r.StatusCode==HttpStatusCode.Forbidden);}
 static string Q(string s){return "'"+s.Replace("'","''")+"'";}
 public static void ValidatePackage(string path){using(var z=ZipFile.OpenRead(path)){if(z.GetEntry(PackageFolder+"/Instalar.ps1")==null)throw new Exception("El paquete no corresponde a esta aplicación.");foreach(var e in z.Entries){string n=e.FullName.Replace('\\','/');if(n.StartsWith("/")||n.Split('/').Any(x=>x==".."||x.Contains(':')))throw new Exception("El paquete contiene una ruta inválida.");if(!n.StartsWith(PackageFolder+"/",StringComparison.Ordinal))throw new Exception("El paquete contiene archivos fuera de la aplicación.");}}}
 public static async void Check(Form owner,Button button){button.Enabled=false;try{string token=Access();Dictionary<string,object> release;try{release=await Task.Run(()=>Release(token));}catch(WebException ex){if(!NeedsAccess(ex))throw;MessageBox.Show(owner,"GitHub no permitió leer una versión publicada. Si el repositorio es privado, configurá acceso de lectura. Si aún no hay una release, primero debe publicarse desde el repositorio.","Actualizaciones",MessageBoxButtons.OK,MessageBoxIcon.Information);if(!Configure(owner))return;token=Access();release=await Task.Run(()=>Release(token));}
 Version latest,current;if(!Version.TryParse(release["tag_name"].ToString().TrimStart('v','V'),out latest)||!Version.TryParse(AppVersion,out current))throw new Exception("La versión publicada no tiene un formato válido.");if(latest<=current){MessageBox.Show(owner,"Ya tenés la última versión ("+AppVersion+").","Actualizaciones");return;}
 var assets=((object[])release["assets"]).Cast<Dictionary<string,object>>();var asset=assets.FirstOrDefault(x=>x["name"].ToString()==PackageName);if(asset==null)throw new Exception("La versión publicada todavía no tiene el paquete instalable esperado.");
 if(MessageBox.Show(owner,"Nueva versión "+latest+".\n¿Descargarla e instalarla ahora? Se conservarán historial y objetivos.","Actualización disponible",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;
 long id=Convert.ToInt64(asset["id"],CultureInfo.InvariantCulture);string temp=Path.Combine(Path.GetTempPath(),AppName.Replace(' ','_')+"_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);string zip=Path.Combine(temp,"actualizacion.zip");button.Text="Descargando...";
 await Task.Run(()=>{using(var w=Web(token,true))w.DownloadFile(Api+"/releases/assets/"+id,zip);object digest;if(asset.TryGetValue("digest",out digest)&&digest!=null&&digest.ToString().StartsWith("sha256:")){using(var stream=File.OpenRead(zip))using(var hash=SHA256.Create()){string actual=BitConverter.ToString(hash.ComputeHash(stream)).Replace("-","").ToLowerInvariant();if(actual!=digest.ToString().Substring(7).ToLowerInvariant())throw new Exception("La verificación de integridad del paquete falló.");}}ValidatePackage(zip);});
 string extract=Path.Combine(temp,"contenido"),script=Path.Combine(temp,"actualizar.ps1"),installer=Path.Combine(extract,PackageFolder,"Instalar.ps1");int pid=Process.GetCurrentProcess().Id;
 File.WriteAllText(script,"$ErrorActionPreference='Stop'\r\ntry {\r\nWait-Process -Id "+pid+" -Timeout 60 -ErrorAction SilentlyContinue\r\nSet-Location "+Q(temp)+"\r\nExpand-Archive -LiteralPath "+Q(zip)+" -DestinationPath "+Q(extract)+" -Force\r\n& "+Q(installer)+"\r\n} catch { Add-Type -AssemblyName System.Windows.Forms; [System.Windows.Forms.MessageBox]::Show($_.Exception.Message,'No se pudo actualizar') | Out-Null }\r\n",Encoding.UTF8);
 Process.Start(new ProcessStartInfo{FileName="powershell.exe",Arguments="-NoProfile -ExecutionPolicy Bypass -File \""+script+"\"",WorkingDirectory=temp,UseShellExecute=true});Application.Exit();
 }catch(WebException){MessageBox.Show(owner,"No se pudo descargar la actualización. Revisá Internet, el permiso de lectura y que exista una versión publicada.","Actualizaciones",MessageBoxButtons.OK,MessageBoxIcon.Warning);}catch(Exception ex){MessageBox.Show(owner,ex.Message,"Actualizaciones",MessageBoxButtons.OK,MessageBoxIcon.Error);}finally{if(!button.IsDisposed){button.Enabled=true;button.Text="Buscar actualizaciones";}}}
}
}
